    "description": "美国科罗拉多大学安舒茨分校和博尔德分校研究团队开发出一款名为Opto2P FCM的微型显微镜，能让科学家在观测动物自由活动时，实时观察并精确控制其单个脑细胞。这一成果有望加速对大脑行为控制机制的研究，并加深对神经系统疾病的理解。相关论文发表于最新一期《光学》杂志。（科技日报）",
