    "description": "美联储周四表示，未来一段时间不会出于准备金管理目的买入美国国库券，这表明决策者认为金融体系中的银行准备金处于合意水平。根据纽约联储网站，纽约联储公开市场操作部门在截至9月14日的月度操作期内，不计划进行准备金管理购买（RMP），但期间仍计划进行约170亿美元的再投资买入。此次暂停表明，尽管政府现金余额增加可能抽走市场流动性，货币当局仍有信心融资市场能够平稳运行。（财联社）",
