    "author": "",
    "description": "瑞士巴塞尔大学和德国慕尼黑工业大学研究人员开发出一种利用光学信号探测维格纳晶体内部电子集体运动的方法。他们发现，光激发产生的激子与维格纳晶体中电子的有序排列发生耦合，可形成具有特征性光学信号的“维格纳晶体极化子”，从而揭示这种特殊量子态此前难以获取的内部动力学信息。相关研究发表于新一期《自然·物理学》杂志。（科技日报）",
    "content": "瑞士巴塞尔大学和德国慕尼黑工业大学研究人员开发出一种利用光学信号探测维格纳晶体内部电子集体运动的方法。他们发现，光激发产生的激子与维格纳晶体中电子的有序排列发生耦合，可形成具有特征性光学信号的“维格纳晶体极化子”，从而揭示这种特殊量子态此前难以获取的内部动力学信息。相关研究发表于新一期《自然·物理学》杂志。（科技日报）"
