    "content": "“辣条第一股”上半年营收净利双增，产品结构持续向蔬菜制品倾斜，辣条业务营收同比下滑。 8月13日晚，卫龙美味全球控股有限公司（卫龙，09985.HK）发布截至2026年6月30日止6个月的中期业绩，总收入为37.15亿元，同比上升6.7%；期内归母利润为7.66亿元，同比上升4.0%；每股基本盈利为0.32元，同比上升3.2%。毛利17.76亿元，同比增长8.1%，毛利率同比提升0.6个百分点至47.8%。 卫龙在财报中表示，营收增加主要是因在报告期内持续加强产品创新和品牌建设，同时积极根据渠道新业态的快速发展以及…"
