    "content": "继收紧渠道补贴政策之后，五粮液又推出“控货挺价”措施。 8月13日，市场消息称，五粮液（000858.SZ）近期向经销商发出通知，不得以低于800元/瓶的价格低价抛售第八代五粮液，同时，酒厂也将加强对低价出货和窜货经销商的处罚。 对此，澎湃新闻记者从五粮液经销商处获悉，上述消息属实。不过，目前五粮液方面尚未就上述消息作出公开回应。 记者还了解到，在终端市场上，不少专卖店、连锁酒行第八代五粮液的零售价都在800元/瓶以上，个别专卖店价格高达850元/瓶。 一位江苏地区的经销商向记者表示，“目前，第八代五粮液售价840…"
