    "title": "“不配合就报警抓父母”？人民日报：岂容网络骗子围猎未成年人",
    "link": "https://m.thepaper.cn/detail/33780301",
    "pub_date": "2026-08-14 07:07:07",
    "author": "张璁/人民日报",
    "description": "预防比惩戒更关键。多方协同发力，才能更好守护未成年人的网络净土 “不配合就报警抓父母”——这句听起来荒诞不经的威胁，却能精准“拿捏”涉世未深的孩子。近年来，网上出现了不少专门针对未成年人的诈骗套路，有的包装成游戏福利，有的以刷单兼职名义诱骗，还有的直接冒充公检法恐吓，造成家庭损失数千甚至数万元。在湖北省襄阳市，当地公安机关破获一起“恐吓式”电诈案：11岁的女孩小张因点击“免费领游戏皮肤”链接，被骗子以“未成年人操作致账户冻结、父母涉嫌违…",
    "content": "预防比惩戒更关键。多方协同发力，才能更好守护未成年人的网络净土 “不配合就报警抓父母”——这句听起来荒诞不经的威胁，却能精准“拿捏”涉世未深的孩子。近年来，网上出现了不少专门针对未成年人的诈骗套路，有的包装成游戏福利，有的以刷单兼职名义诱骗，还有的直接冒充公检法恐吓，造成家庭损失数千甚至数万元。在湖北省襄阳市，当地公安机关破获一起“恐吓式”电诈案：11岁的女孩小张因点击“免费领游戏皮肤”链接，被骗子以“未成年人操作致账户冻结、父母涉嫌违规将被拘留”为由要挟，女孩趁家长熟睡时转账约5万元。 现在的孩子是互联网“原住民…"
