    "content": "这两天，费大厨因为撤下“全国小炒肉大王”宣传上了热搜。门店招牌、宣传物料上的“大王”字样陆续被撤，取而代之的是“精选黑猪肉，专业大厨炒”。 这次改口的直接原因，是网友扒出这个用了近6年的称号，来自2020年中国烹饪协会举办的一场线上比赛。参赛者只需上传视频和照片，评委全程不用尝菜。评菜不用嘴，隔着屏幕就评出了“全国小炒肉大王”。 而更大的政策背景是，8月1日起，《社会组织评比表彰活动管理办法》正式施行，中国烹饪协会随即公告全面清理撤销历年颁发的“大师”“名师”等称号。费大厨的“大王”称号，刚好撞在了枪口上。 从“大…"
