    "link": "http://www.news.cn/20260814/8b3883ee72f34384b08c15748a118b6a/c.html",
    "pub_date": "2026-08-14 06:20:04",
    "author": "徐皓夫,姚兵",
    "description": "新华社开罗8月13日电（记者徐皓夫 姚兵）埃及首都开罗市一家购物中心13日发生氦气瓶爆炸事故，造成至少3人死亡、17人受伤。 埃及内政部当天发表声明说，事故由该购物中心底层一家礼品店内氦气瓶爆炸引起，火势已得到控制。埃及卫生和人口部同日发表声明说，事故已造成3人死亡，另有17名伤者被送往医院救治。",
    "content": "新华社开罗8月13日电（记者徐皓夫 姚兵）埃及首都开罗市一家购物中心13日发生氦气瓶爆炸事故，造成至少3人死亡、17人受伤。 埃及内政部当天发表声明说，事故由该购物中心底层一家礼品店内氦气瓶爆炸引起，火势已得到控制。埃及卫生和人口部同日发表声明说，事故已造成3人死亡，另有17名伤者被送往医院救治。"
