    "content": "新华社纽约8月13日电 纽约股市三大股指13日上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨69.72点，收于53839.99点，涨幅为0.13%；标准普尔500种股票指数上涨50.49点，收于7798.99点，涨幅为0.65%；纳斯达克综合指数上涨214.54点，收于26803.03点，涨幅为0.81%。 板块方面，标普500指数十一大板块七涨四跌。通信服务板块和房地产板块分别以1.56%和1.34%涨幅领涨，材料板块和能源板块分别以0.73%和0.09%跌幅领跌。"
