    "pub_date": "2026-08-14 04:11:35",
    "author": "于艾岑",
    "description": "新华社伦敦8月13日电（记者于艾岑）据英国铁路警察局13日消息，一列火车当天15时54分许在英格兰地区东萨塞克斯郡刘易斯火车站附近脱轨。当地急救部门说，车上150人中的11人受伤，其中两人伤势严重。 英国铁路警察局宣布，该事故构成“重大事故”。社交媒体上流传的照片显示，有火车车厢在事故中侧翻。 事故导致周边地区运营的大量铁路服务延误或取消。英国交通大臣海迪·亚历山大在社交媒体上表示，事故令人“深感担忧”，正与铁路行业和当地合作方协作帮助…",
    "content": "新华社伦敦8月13日电（记者于艾岑）据英国铁路警察局13日消息，一列火车当天15时54分许在英格兰地区东萨塞克斯郡刘易斯火车站附近脱轨。当地急救部门说，车上150人中的11人受伤，其中两人伤势严重。 英国铁路警察局宣布，该事故构成“重大事故”。社交媒体上流传的照片显示，有火车车厢在事故中侧翻。 事故导致周边地区运营的大量铁路服务延误或取消。英国交通大臣海迪·亚历山大在社交媒体上表示，事故令人“深感担忧”，正与铁路行业和当地合作方协作帮助乘客。"
