    "description": "不过可能也就是我自己蠢，V2 上的大佬们都知道了。 我一直想做系统程序员，但是没有多少计算机基础。之前自学计算机基础，跟着网课和书本做了两三个项目，比如 MIT 的 xv6 labs 、写了个小的解释器，等等。每个项目花 2-4 个月不等。 但是后来我发现，学习这些用不上的东西，一方面容易疲劳，另一方面似乎对自己的职业也没有任何帮助。说到疲劳，我每次做完一个项目，就会陷入大概半年左右的挣扎期。在这段时间内会不断的尝试新的项目，但是始终做…",
    "content": "不过可能也就是我自己蠢，V2 上的大佬们都知道了。 我一直想做系统程序员，但是没有多少计算机基础。之前自学计算机基础，跟着网课和书本做了两三个项目，比如 MIT 的 xv6 labs 、写了个小的解释器，等等。每个项目花 2-4 个月不等。 但是后来我发现，学习这些用不上的东西，一方面容易疲劳，另一方面似乎对自己的职业也没有任何帮助。说到疲劳，我每次做完一个项目，就会陷入大概半年左右的挣扎期。在这段时间内会不断的尝试新的项目，但是始终做不下去，最后放弃，直到六个月之后才能完全好转。而职业上这些东西又用不到，或者说要…"
