    "description": "新华社雅典8月13日电（记者陈刚）据希腊国家广播电视公司13日报道，希腊北部哈尔基季基半岛度假胜地锡维里当天发生大规模森林火灾。受强风影响，火势迅速蔓延，造成数百人被疏散、两名消防员受伤。 报道说，火灾于当天下午发生，初步调查显示，树木被强风吹倒后砸落电缆并产生火花可能是起火原因。受强风影响，火势从低矮植被迅速蔓延至松林和居民区，过火线超过3公里。截至13日傍晚，浓烟蔓延至更广范围，一些房屋和车辆被大火烧毁。当地供电系统已瘫痪，供水也受…",
    "content": "新华社雅典8月13日电（记者陈刚）据希腊国家广播电视公司13日报道，希腊北部哈尔基季基半岛度假胜地锡维里当天发生大规模森林火灾。受强风影响，火势迅速蔓延，造成数百人被疏散、两名消防员受伤。 报道说，火灾于当天下午发生，初步调查显示，树木被强风吹倒后砸落电缆并产生火花可能是起火原因。受强风影响，火势从低矮植被迅速蔓延至松林和居民区，过火线超过3公里。截至13日傍晚，浓烟蔓延至更广范围，一些房屋和车辆被大火烧毁。当地供电系统已瘫痪，供水也受到影响。 希腊消防部门说，已调集155名消防员，并出动消防飞机、直升机及数十辆车…"
