    "content": "13/08/2026 - 21:01 俄罗斯周四（8月13日）驳斥了日本在俄罗斯总统普京访问千岛群岛后提出的“毫无根据”的批评，并指责东京存在“历史修正主义”行为。据悉，千岛群岛是俄日两国数十年来领土争端的核心。 当天早些时候，俄罗斯总统普京首次访问了位于俄罗斯远东地区的千岛群岛。 日本方面则称此次访问“绝对不可接受”。 日本一直声称拥有千岛群岛南部 四座岛屿 的主权。据悉，这些岛屿于1945年第二次世界大战即将结束之际被苏联军队占领。 面对日本的强烈抗议，当天晚些时候，俄罗斯外交部发言人扎哈罗娃在一份声明中回应称…"
