    "description": "新华社莫斯科8月13日电 俄罗斯外交部长拉夫罗夫13日对俄媒表示，俄方将“自行决定”扣押哪些西方国家船只，作为对西方国家扣押俄船只行为的反制。 拉夫罗夫说，西方国家把“强盗行径和海盗行为”当作官方政策，俄罗斯将从服务于西方国家利益的船只中自主选择扣押目标，至于如何处理“将由俄方自行决定”。 西方国家指责俄罗斯利用油轮等商用船只逃避西方制裁，将这些商用船只称为“影子舰队”。欧洲多国近来在相关水域拦截多艘所谓俄“影子舰队”船只。 拉夫罗夫表…",
    "content": "新华社莫斯科8月13日电 俄罗斯外交部长拉夫罗夫13日对俄媒表示，俄方将“自行决定”扣押哪些西方国家船只，作为对西方国家扣押俄船只行为的反制。 拉夫罗夫说，西方国家把“强盗行径和海盗行为”当作官方政策，俄罗斯将从服务于西方国家利益的船只中自主选择扣押目标，至于如何处理“将由俄方自行决定”。 西方国家指责俄罗斯利用油轮等商用船只逃避西方制裁，将这些商用船只称为“影子舰队”。欧洲多国近来在相关水域拦截多艘所谓俄“影子舰队”船只。 拉夫罗夫表示，所有不遵从欧盟要求的船只，无论悬挂何种旗帜，都被欧盟划定为“影子舰队”。欧盟…"
