    "description": "",
    "content": "据媒体报道，比利时网红Michiel Vandeweert去世，享年28岁，是医生最初预计他寿命的两倍多。 Michiel Vandeweert年幼时被诊断患有早衰症（progeria），这是一种极其罕见的遗传性疾病，会导致身体快速衰老。医生曾预测他只能活到12岁，但他打破了这一预期，成为全球患有这种疾病的最长寿者之一。 据了解，早衰症患者的平均预期寿命约为15岁。目前这种疾病尚无治愈方法，不过一些治疗手段可以帮助控制相关症状和并发症。 Michiel Vandeweert在Instagram、YouTube和Tw…"
