    "content": "快科技8月14日消息，据媒体报道， 近日，有网友在社交平台爆料称河南方中山胡辣汤将在英国伦敦开店，也是全球海外的首店。 对此，方中山品牌运营总监表示，方中山胡辣汤将在伦敦开店确有此事，店铺选址就在伦敦的大英博物馆附近，两者距离走路也就三五分钟，预计今年9月中下旬具备开业条件。 事实上，相关工作从今年年初已就已经开始了，历经8个月，从人员培训、物料准备、海关通关等，现在进行到了装修阶段。 据悉，方中山胡辣汤伦敦店的所有菜品结构和制作标准会继续和郑州总店保持高度一致，例如大家熟悉的胡辣汤、牛肉盒、水煎包、蒸包和葱油饼这…"
