    "content": "新华社海牙8月13日电（记者邵海军 李弘）荷兰鹿特丹警方13日初步确认，当天发生在鹿特丹港一家能源公司厂区的爆炸属于工作事故。 警方在声明中说，目前来看爆炸是一起工作事故。荷兰社会事务与就业部将对事故进行继续调查，并负责处理后续事宜。 当天，贡沃尔石油贸易公司在鹿特丹港的储油罐区发生爆炸。该公司新闻发言人告诉新华社记者，爆炸发生在上午11点30分左右，当时一支维修队正在维修管道。爆炸已造成1人死亡、6人受伤。应急救援人员已在现场开展救援工作。 另据荷兰安全机构的消息，鹿特丹港当天还发生多起事故，包括停电、高压变电站…"
