    "author": "张华迎,董建国,郭圻",
    "description": "新华社福州8月13日电 记者从福建省宁德市福安市消防救援局获悉，8月13日13时09分，福安市甘棠镇华海船厂着火。接报后，福安市消防救援局第一时间调派力量前往处置。13时25分，辖区消防站到场展开灭火救援。14时10分，现场突然发生爆炸，造成10名消防救援人员和2名群众受伤，均已送医救治。18时50分，1名消防救援人员经抢救无效不幸牺牲。目前，现场火势已得到有效控制，起火原因正在进一步调查中。",
