    "content": "新华社澳门8月13日电（记者齐菲、宋晨）澳门特区立法会13日下午举行全体会议，通过紧急程序，表决通过《修改第17/2009号法律〈禁止不法生产、贩卖和吸食麻醉药品及精神药物〉》法案，将13种物质列为该法附表所定的受规管麻醉药品及精神药物。 法案纳入该法所规定的受规管药物包括：2025年联合国麻醉药品委员会第68届会议决定新增的6种国际列管物质，以及因常被添加于电子烟油中滥用，而被内地及香港列为受管的7种物质。 特区政府保安司司长陈子劲引介法案时表示，为履行国际公约义务，同时亦为积极主动应对新型毒品对公共健康造成的风…"
