    "description": "8月13日，美联储今年票委、克利夫兰联储主席Beth Hammack和今年为候补票委的里士满联储主席Tom Barkin分别发表讲话。面对仍具韧性的美国经济和持续高于目标的通胀，两位美联储官员释放出不同政策信号。 Hammack在讲话中释放明确鹰派信号。她表示，目前美国货币政策的限制性仍然不足，通胀已经持续偏离美联储2%的目标，而就业市场整体保持稳定，因此美联储仍有必要通过收紧政策进一步压低通胀。 针对市场热议的“美联储是否会上调通胀目…",
    "content": "8月13日，美联储今年票委、克利夫兰联储主席Beth Hammack和今年为候补票委的里士满联储主席Tom Barkin分别发表讲话。面对仍具韧性的美国经济和持续高于目标的通胀，两位美联储官员释放出不同政策信号。 Hammack在讲话中释放明确鹰派信号。她表示，目前美国货币政策的限制性仍然不足，通胀已经持续偏离美联储2%的目标，而就业市场整体保持稳定，因此美联储仍有必要通过收紧政策进一步压低通胀。 针对市场热议的“美联储是否会上调通胀目标”问题，哈马克给出明确否定回应，强调美联储2%的通胀目标不会改变。她认为，目前…"
