    "content": "新华社台北8月13日电（记者黄扬、马欣然）台当局经济事务主管部门日前会同多部门，于台湾新北市查扣首辆入台“张雪机车”820RR。民众批评此举是政治操弄，滥用权力限阻两岸交流。 今年3月以来，“张雪机车”在世界超级机车锦标赛多次夺冠，成为“机车之岛”台湾的热议话题，夺冠同款的量产820RR令不少台湾车迷神往。据了解，岛内落地的首台“张雪机车”820RR系网名“小飞哥”的台湾工程师王先生与网络博主“米亚”将整车拆解后分批运输回台、历时一个半月亲手组装而成，一经展览便引发围观热潮。 王先生12日首度通过社交媒体公开回应，…"
