    "content": "IT之家 8 月 13 日消息，据北京亦庄公众号消息，京东近日率先在辖区规模化落地 X1 智能控温餐箱， 亦庄正式成为全国首个智能控温餐箱全覆盖示范区 ，苏州、金华、宿迁等城市也已同步开启落地推广。 相较于传统配送装备，X1 智能控温餐箱具备分区控温、密封防尘、智能消杀三大核心优势。餐箱内部采用物理隔断设计，划分独立冷热双区， 冷区温控区间为-5℃ 至 15℃、热区稳定维持 40℃ 至 55℃ ，两区互不干扰、精准锁温， 可实现冷热餐品同箱配送 。 在防护性能上，区别于市面常规搭扣、敞口式餐箱，X1 餐箱采用全锁扣…"
