    "content": "感谢IT之家网友 鬼谷 的线索投递！ IT之家 8 月 13 日消息，开源咨询公司 Igalia 的工程师 Hyun-jun Ko 昨日在 Mesa 26.3 开发版中合并了一项重要更新，正式为英特尔锐炫 A 系列 DG2/Alchemist 显卡启用了 Vulkan Video AV1 视频编码功能。 这意味着锐炫 A 系列显卡在 Linux 平台 Vulkan 生态中的编解码能力终于形成了完整闭环，此前长期缺失的 AV1 硬件编码短板已被补齐。 IT之家注：AV1 是由 AOM（开放媒体联盟）开发的开源视频编码…"
