    "content": "新华社香港8月13日电 “海星之愿”特需儿童艺术启发公益项目香港首演启动仪式13日在香港艺穗会举行。 本次活动由上海市政府港澳办指导、中国福利会主办、荣威·上海儿童艺术剧场承办，得到香港赛马会、东华三院、艺穗会、香港特殊教育学校校长联会等支持，旨在深化沪港特需儿童美育交流，推动特需儿童公益事业协同发展。 作为内地专注特需儿童艺术启发的公益项目，“海星之愿”立足特需儿童身心特点，量身设计沉浸式戏剧，适配孤独症、智力障碍、唐氏综合征、脑瘫等特殊群体的观演需求。 中国福利会副主席王玉峰在启动仪式上致辞说，“海星之愿”公益…"
