    "content": "新华社成都8月13日电（记者吴晓颖）针对西南医科大学中西医结合学院辅导员在年级QQ群发布教材选购不当言论一事，13日该校官方发布情况通报称，已对该辅导员予以严肃批评教育，并责令其在年级QQ群公开致歉。 近日，社交平台流传的西南医科大学班级群通知截图在网上引发关注。网传截图中，该校中西医结合学院一名辅导员发布班级群消息，要求学生通过教务处提供的小程序购买教材，并表示“不允许在其他渠道购买教材，也不要购买二手教材、电子书之类的”。该辅导员还称，“如果连教材都不舍得买，或者还要计较那一点与旧书的差价，这个书也可以不读了，…"
