    "content": "新华社莫斯科/东京8月13日电 俄罗斯联邦安全会议副主席、统一俄罗斯党主席梅德韦杰夫13日说，南千岛群岛（日本称北方四岛）“过去、现在、将来都是俄罗斯的领土”，日本首相高市早苗的有关言论“不会改变任何事”。 13日早些时候，高市举行记者会，强烈抗议俄总统普京当天登上争议岛屿。高市称，北方四岛是日本的“固有领土”，对普京此举“绝对无法接受”。她还称，普京此举进一步恶化了日本民众对俄罗斯的看法，也让中长期内恢复两国关系变得困难。 梅德韦杰夫在社交媒体上表示，高市随意表态称“南千岛群岛向来是日本的”，“这种胡言乱语不会改…"
