    "content": "这是8月13日在日本千叶县拍摄的被雨水淹没的道路。新华社/共同社 新华社东京8月13日电（记者陈泽安 李子越）受暖湿气流与冷空气影响，包括东京在内的日本关东地区13日遭遇强降雨，导致数万户用户停电，并发生山体滑坡。 日本气象厅当晚对千叶县的多个市发布5级大雨特别警报，这是日本降雨预警系统中的最高级别警报。气象厅说，截至当地时间19时的一个小时内，千叶县八千代市附近的降雨量达到约120毫米，四街道市附近的降雨量达约100毫米。 日本广播协会报道称，截至当地时间20时45分，千叶县内有超过4.6万户用户停电。当地存在发…"
