    "title": "一名俄军人员在克里米亚遇袭身亡",
    "link": "http://www.news.cn/20260813/ae12fdbbf96a4524a0afc1c9eb541f2a/c.html",
    "pub_date": "2026-08-13 21:45:24",
    "author": "栾海",
    "description": "新华社莫斯科8月13日电 俄罗斯联邦安全局13日发布消息说，一名俄军人员当天在克里米亚地区的黑海港口城市塞瓦斯托波尔被炸身亡，乌克兰情报部门指使实施此次袭击。 俄联邦安全局的消息说，一名俄罗斯籍女性嫌疑人当天在塞瓦斯托波尔实施爆炸袭击，导致一名俄军人员死亡。在当地民众帮助下，该嫌疑人在案发后不久被抓获。初步调查显示，这名嫌疑人在乌克兰情报部门指使下实施了这起爆炸案。目前执法人员已封锁案发现场，并继续调查。",
    "content": "新华社莫斯科8月13日电 俄罗斯联邦安全局13日发布消息说，一名俄军人员当天在克里米亚地区的黑海港口城市塞瓦斯托波尔被炸身亡，乌克兰情报部门指使实施此次袭击。 俄联邦安全局的消息说，一名俄罗斯籍女性嫌疑人当天在塞瓦斯托波尔实施爆炸袭击，导致一名俄军人员死亡。在当地民众帮助下，该嫌疑人在案发后不久被抓获。初步调查显示，这名嫌疑人在乌克兰情报部门指使下实施了这起爆炸案。目前执法人员已封锁案发现场，并继续调查。"
