    "content": "中新社北京8月13日电 (记者 阮煜琳)中国生态环境部等六部门近日联合印发《生态保护“十五五”规划》。生态环境部自然生态保护司有关负责人13日解读该文件时对记者表示，《规划》提出，到2030年，生态空间格局持续优化，生态质量稳步改善，生物多样性丧失趋势得到有效缓解。"
