    "content": "13/08/2026 - 15:09 一名中国留学生因使用无人机非法拍摄停泊有美国海军航空母舰及其他舰艇的釜山海军基地，在一审中被判入狱；他在上诉期间继续对案件的法律依据提出异议，主张“一般利敌罪”的指控适用不当。 今年6月，韩国釜山地方法院刑事审判第5庭以涉嫌“一般利敌罪”并违反《军事基地及军事设施保护法》为由，判处A某有期徒刑1年6个月。与A某一同被起诉的B某被判有期徒刑1年，缓刑2年。法院表示，被告人未经许可擅自拍摄韩国军事设施，给韩国的军事利益构成严重威胁。 周四（13日），釜山高等法院刑事第1庭对被指控犯…"
