    "content": "新华社香港8月13日电（奚天麒）香港特区政府新闻处13日发布消息，特区政府当日在皇岗口岸港方口岸区举行大型演练，以测试口岸联检大楼和公共运输交汇处的人流及车流整体管理，为日后口岸正式开通作好准备。 皇岗口岸港方口岸区7月31日零时正式成立，由香港特区依照本地法律实施管辖。 此次演练动员约1000名来自超过20个特区政府部门的公务员参与。他们按指示乘搭不同公共交通工具，包括专营巴士、短途跨境巴士、专线小巴及的士，抵达位于联检大楼二楼的公共运输交汇处。随后前往五楼离境大堂，并转往四楼入境大堂，然后返回二楼的公共运输交汇…"
