    "content": "新华社武汉8月13日电（记者张阳）我国高速公路服务区已建成充电基础设施（枪）8.54万个，覆盖全国超98%的服务区。这是记者从13日在湖北武汉召开的2026交通与能源融合创新发展大会上获悉的。 目前，我国充电基础设施数量显著增多，布局日益完善，结构持续优化。截至2026年6月底，全国高速公路服务区累计建成充电基础设施（枪）8.54万个，除部分高寒、高海拔地区外，基本实现全覆盖。今年上半年，我国公共充电基础设施充电电量587.6亿度，同比增长60.2%。 会上公布的一系列数据，体现出交通和能源融合发展正不断深入。 交…"
