    "title": "防灾减灾救灾一线见闻丨淮委水文局已升级发布沙颍河漯河站洪水红色预警",
    "link": "http://www.news.cn/20260813/e9b3a7252e9d4e9d90ef13ade4c66502/c.html",
    "pub_date": "2026-08-13 20:56:15",
    "author": "白斌,周牧",
    "description": "8月13日，安徽启用茨淮新河分泄颍河洪水，全力降低颍河水位。受台风“白海豚”残余环流影响，淮河流域沙颍河漯河站13日2时水位涨至61.87米，超过保证水位0.17米并继续上涨。水利部淮河水利委员会水文局已升级发布洪水红色预警。 从13日11时开始，茨河铺分洪闸开闸分洪，17孔闸门到中午12时全部打开，闸门提高1.3米，洪水下泄流量从最开始的每秒50立方米提升到每秒1000立方米。 作者：白斌、周牧、田晨 摄制：帅玉豪 新华社音视频部制作",
    "content": "8月13日，安徽启用茨淮新河分泄颍河洪水，全力降低颍河水位。受台风“白海豚”残余环流影响，淮河流域沙颍河漯河站13日2时水位涨至61.87米，超过保证水位0.17米并继续上涨。水利部淮河水利委员会水文局已升级发布洪水红色预警。 从13日11时开始，茨河铺分洪闸开闸分洪，17孔闸门到中午12时全部打开，闸门提高1.3米，洪水下泄流量从最开始的每秒50立方米提升到每秒1000立方米。 作者：白斌、周牧、田晨 摄制：帅玉豪 新华社音视频部制作"
